import warnings

import pytest
from flaskbb import app as flaskbb_app
from flaskbb.app import configure_app
from flaskbb.configs.default import DefaultConfig
from flaskbb.core.app import FlaskBB
from flaskbb.deprecation import RemovedInFlaskBB4

# the lines of a config file generated by FlaskBB 2.0 that changed since
FLASKBB_2_CONFIG = """
import os
from flaskbb.configs.default import DefaultConfig

TESTING = True
WHOOSHEE_DIR = os.path.join(DefaultConfig.basedir, "whoosh_index", DefaultConfig.py_version)
CELERY_BROKER_URL = "redis://redis.example.org:6379"
RATELIMIT_STORAGE_URL = "redis://redis.example.org:6379"
CACHE_TYPE = "simple"
"""


@pytest.fixture
def load_config(tmp_path, monkeypatch):
    # keeps the logging setup of the test session
    monkeypatch.setattr(flaskbb_app, "configure_logging", lambda app: None)

    def load(content):
        path = tmp_path / "flaskbb.cfg"
        path.write_text(content)
        app = FlaskBB("flaskbb", instance_path=str(tmp_path))
        configure_app(app, str(path))
        return app

    return load


def test_flaskbb_2_config_still_works(load_config):
    with pytest.warns(RemovedInFlaskBB4) as deprecations:
        app = load_config(FLASKBB_2_CONFIG)

    assert app.config["CACHE_TYPE"] == "SimpleCache"
    assert app.config["RATELIMIT_STORAGE_URI"] == "redis://redis.example.org:6379"
    assert app.config["CELERY_CONFIG"]["broker_url"] == "redis://redis.example.org:6379"
    assert "CELERY_BROKER_URL" not in app.config
    assert len(deprecations) == 3


def test_flaskbb_2_celery_settings_leave_the_defaults_alone(load_config):
    with pytest.warns(RemovedInFlaskBB4):
        load_config(FLASKBB_2_CONFIG)

    assert DefaultConfig.CELERY_CONFIG["broker_url"] == "redis://localhost:6379"


def test_current_config_is_left_alone(load_config):
    with warnings.catch_warnings():
        warnings.simplefilter("error", RemovedInFlaskBB4)
        app = load_config(
            'TESTING = True\nCACHE_TYPE = "RedisCache"\nRATELIMIT_STORAGE_URI = "memory://"\n'
        )

    assert app.config["CACHE_TYPE"] == "RedisCache"
    assert app.config["RATELIMIT_STORAGE_URI"] == "memory://"
